def getDbAccess():
    args = getArgs()
    data = checkArgs(args, ['name'])
    if not data[0]:
        return data[1]

    dbname = args['name']
    if not checkSafeName(dbname):
        return yf.returnJson(False, '数据库名称不合法！')

    psdb = pSqliteDb('databases')
    db_info = psdb.where('name=?', (dbname,)).field('username,accept').find()

    accept = '127.0.0.1/32'
    dbuser = dbname
    if db_info:
        if 'accept' in db_info and db_info['accept']:
            accept = db_info['accept']
        if 'username' in db_info and db_info['username']:
            dbuser = db_info['username']

    privileges_list = []
    try:
        pdb = pgDb(dbname)
        sql = """SELECT 
            pg_get_userbyid(d.defaclrole) AS grantor,
            COALESCE(n.nspname, 'ALL_SCHEMAS') AS schema,
            CASE d.defaclobjtype
                WHEN 'r' THEN 'TABLES'
                WHEN 'S' THEN 'SEQUENCES'
                WHEN 'f' THEN 'FUNCTIONS'
                WHEN 'T' THEN 'TYPES'
                WHEN 'n' THEN 'SCHEMAS'
            END AS object_type,
            d.defaclacl::text AS privileges
        FROM pg_default_acl d
        LEFT JOIN pg_namespace n 
               ON d.defaclnamespace = n.oid;"""
        res = pdb.query(sql)
        if isinstance(res, list):
            for row in res:
                privileges_list.append({
                    'grantor': str(row[0]),
                    'schema': str(row[1]),
                    'object_type': str(row[2]),
                    'privileges': str(row[3])
                })
    except Exception as e:
        pass

    res_data = {
        'accept': accept,
        'username': dbuser,
        'privileges': privileges_list
    }
    return yf.returnJson(True, accept, res_data)


