    sqls = [
        "GRANT USAGE ON SCHEMA public TO {}".format(dbuser),
        "GRANT CREATE ON SCHEMA public TO {}".format(dbuser),
        "GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO {}".format(dbuser),
