        yf.makeDirs(bk_path)
    return bk_path


def checkArgs(data, ck=[]):
    for i in range(len(ck)):
        if not ck[i] in data:
            return (False, yf.returnJson(False, '参数:(' + ck[i] + ')没有!'))
    return (True, yf.returnJson(True, 'ok'))


def getConf():
    path = getServerDir() + '/data/postgresql.conf'
    return path


def configTpl():

    clist = []

    app_dir = getServerDir()
    clist.append(app_dir + "/data/postgresql.conf")
    clist.append(app_dir + "/data/pg_hba.conf")

    return yf.getJson(clist)


def pgHbaConf():
    return getServerDir() + "/data/pg_hba.conf"


def readConfigTpl():
    args = getArgs()
    data = checkArgs(args, ['file'])
    if not data[0]:
        return data[1]

    content = yf.readFile(args['file'])
    return yf.returnJson(True, 'ok', content)


def getDbPort():
    file = getConf()
    content = yf.readFile(file)
    rep = r'port\s*=\s*(\d*)?'
    tmp = re.search(rep, content)
    return tmp.groups()[0].strip()


def getSocketFile():
    # sock_name = '.s.PGSQL.' + getDbPort()
    sock_name = ""
    sock_tmp = '/tmp/' + sock_name
    if os.path.exists(sock_tmp):
        return sock_tmp

    sock_app = getServerDir() + "/" + sock_name
    if os.path.exists(sock_app):
        return sock_app
    return sock_app


def getInitdTpl(version=''):
    path = getPluginDir() + '/init.d/postgresql.tpl'
    if not os.path.exists(path):
        path = getPluginDir() + '/init.d/postgresql.tpl'
    return path


def contentReplace(content):
    service_path = yf.getServerDir()
    content = content.replace('{$ROOT_PATH}', yf.getFatherDir())
    content = content.replace('{$SERVER_PATH}', service_path)
    content = content.replace('{$APP_PATH}', getServerDir())
    return content


def pSqliteDb(dbname='databases', name='pgsql'):
    file = getServerDir() + '/' + name + '.db'
    if not os.path.exists(file):
        conn = yf.M(dbname).dbPos(getServerDir(), name)
        csql = yf.readFile(getPluginDir() + '/conf/pgsql.sql')
        csql_list = csql.split(';')
        for index in range(len(csql_list)):
            conn.execute(csql_list[index], ())
    else:
        # 现有run
