def pgDb(dbname='postgres'):

    sys.path.append(getPluginDir() + "/class")
    import pg

    db = pg.ORM()

    db.setPort(getDbPort())
    db.setPwd(pSqliteDb('config').where('id=?', (1,)).getField('pg_root'))
    db.setSocket(getSocketFile())
    db.setDbName(dbname)
    return db


def initConfig(version=''):
    conf_dir = getServerDir()
    init_pl = conf_dir + "/init.pl"
    if not os.path.exists(init_pl):
        yf.writeFile(init_pl, 'ok')

        # postgresql.conf
        pg_conf = conf_dir + '/data/postgresql.conf'
        tpl = getPluginDir() + '/conf/postgresql.conf'
        content = yf.readFile(tpl)
        content = contentReplace(content)
        yf.writeFile(pg_conf, content)

        # pg_hba.conf
        tpl = getPluginDir() + '/conf/pg_hba.conf'
        pg_hba_conf = conf_dir + '/data/pg_hba.conf'
        content = yf.readFile(tpl)
        yf.writeFile(pg_hba_conf, content)

        logfile = runLog()
        if not os.path.exists(logfile):
            yf.writeFile(logfile, '')


def initDreplace(version=''):

    conf_dir = getServerDir()
    conf_list = [
        conf_dir + "/logs",
        conf_dir + "/tmp",
        conf_dir + "/archivelog",
    ]
    for c in conf_list:
        if not os.path.exists(c):
            os.mkdir(c)

    # systemd
    system_dir = yf.systemdCfgDir()
    service = system_dir + '/postgresql.service'
    if os.path.exists(system_dir):
        # 清理旧版本的 init.d 脚本
        if os.path.exists('/etc/init.d/postgresql'):
            yf.execShell('rm -f /etc/init.d/postgresql')

        # 清理旧路径下的同名服务，统一使用 /etc/systemd/system 作为标准配置目录
        if os.path.exists('/lib/systemd/system/postgresql.service'):
            yf.execShell('rm -f /lib/systemd/system/postgresql.service')
        if os.path.exists('/usr/lib/systemd/system/postgresql.service'):
            yf.execShell('rm -f /usr/lib/systemd/system/postgresql.service')

        tpl = getPluginDir() + '/init.d/postgresql.service.tpl'
        service_path = yf.getServerDir()
        content = yf.readFile(tpl)
        content = contentReplace(content)

        # 将标准配置写入优先级最高的 /etc/systemd/system/ 目录，直接覆盖宝塔残留配置
        systemServiceEtc = '/etc/systemd/system/postgresql.service'
        if not os.path.exists(systemServiceEtc) or yf.readFile(systemServiceEtc) != content:
            yf.writeFile(systemServiceEtc, content)
            yf.execShell('systemctl daemon-reload')

    if not yf.isAppleSystem():
        yf.execShell('chown -R postgres:postgres ' + getServerDir())

    initd_path = getServerDir() + '/init.d'
    if not os.path.exists(initd_path):
        os.mkdir(initd_path)

    file_bin = initd_path + '/' + getPluginName()
    if True:
        tpl = getInitdTpl(version)
        content = yf.readFile(tpl)
        content = contentReplace(content)
        yf.writeFile(file_bin, content)
        yf.execShell('chmod +x ' + file_bin)
    return file_bin


def status(version=''):
    if not yf.isAppleSystem():
        # 1. 优先使用 systemctl 精准探测
        state_data = yf.execShell("systemctl is-active postgresql")
        if state_data[0].strip() == "active":
            return 'start'

        # 2. 备用检测：解析 postmaster.pid 文件获取真实 PID 并验证 /proc 状态
        pid_file = getServerDir() + "/data/postmaster.pid"
        if os.path.exists(pid_file):
            try:
                content = yf.readFile(pid_file)
                if content:
                    lines = content.strip().split('\n')
                    if len(lines) > 0:
                        pid = lines[0].strip()
                        if pid.isdigit() and os.path.isdir("/proc/" + pid):
                            return 'start'
            except:
                pass
        return 'stop'
    else:
        data = yf.execShell(
            "ps -ef|grep postgres |grep -v grep | grep -v python | grep -v mdserver-web | awk '{print $2}'")
        if data[0] == '':
            return 'stop'
        return 'start'


