def pgOp(version, method):
    # import commands
    init_file = initDreplace()
    cmd = init_file + ' ' + method
    # print(cmd)
    try:
        isInited = initPgData()
        initConfig(version)
        if not isInited:
            if yf.isAppleSystem():
                cmd_init_start = [init_file, 'start']
                subprocess.Popen(cmd_init_start, stdout=subprocess.PIPE, shell=False,
                                 bufsize=4096, stderr=subprocess.PIPE)

                time.sleep(6)
            else:
                yf.execShell('systemctl start postgresql')

            initPgPwd()

            if yf.isAppleSystem():
                cmd_init_stop = [init_file, 'stop']
                subprocess.Popen(cmd_init_stop, stdout=subprocess.PIPE, shell=False,
                                 bufsize=4096, stderr=subprocess.PIPE)
                time.sleep(3)
            else:
                yf.execShell('systemctl stop postgresql')

        if yf.isAppleSystem():
            sub = subprocess.Popen([init_file, method], stdout=subprocess.PIPE, shell=False,
                                   bufsize=4096, stderr=subprocess.PIPE)
            sub.wait(5)
        else:
            yf.execShell('systemctl ' + method + ' postgresql')
        return 'ok'
    except Exception as e:
        # raise
        return method + ":" + str(e)


