def getDbBackupListFunc(dbname='', is_sync=False):
    bkDir = getBackupDir()
    if not os.path.exists(bkDir):
        return []
    blist = os.listdir(bkDir)
    r = []

    version = getPgVersion()
    parts = version.split('.')
    if len(parts) >= 2:
        ver_str = parts[0] + parts[1]
    elif len(parts) == 1:
        ver_str = parts[0]
    else:
        ver_str = '183'
    postgre_prefix = 'postgre' + ver_str + '_' + dbname + '_'

    for x in blist:
        if not x.endswith('.gz'):
            continue
        if is_sync:
            r.append(x)
        else:
            is_match = False
            # 1. 动态前缀格式: postgre{ver_str}_{dbname}_{cur_time}.gz
            if x.startswith(postgre_prefix):
                is_match = True

            # 2. 兼容最新体现版本号的命名格式: pg_backup_v{version}_{dbname}_{cur_time}.gz
            if not is_match:
                if x.startswith('pg_backup_v') and ('_' + dbname + '_') in x:
                    is_match = True

            # 3. 兼容 db_dbname_ 和 dbname_ 的历史格式
            if not is_match:
                match_prefixes = ['db_' + dbname + '_', dbname + '_']
                for prefix in match_prefixes:
                    if x.startswith(prefix):
                        is_match = True
                        break

            # 4. 兼容直接等于 db_dbname.gz 或 dbname.gz
            if not is_match and (x == 'db_' + dbname + '.gz' or x == dbname + '.gz'):
                is_match = True

            # 5. 兼容直接等于 postgre{ver_str}_{dbname}.gz
            if not is_match and x == 'postgre' + ver_str + '_' + dbname + '.gz':
                is_match = True

            if is_match:
                r.append(x)
    return r


def setDbBackup():
    args = getArgs()
    data = checkArgs(args, ['name'])
    if not data[0]:
        return data[1]

    dbname = args['name']
    if not checkSafeName(dbname):
        return yf.returnJson(False, '数据库名称不合法！')

    cur_time = time.strftime('%Y%m%d_%H%M%S')
    version = getPgVersion()
    parts = version.split('.')
    if len(parts) >= 2:
        ver_str = parts[0] + parts[1]
    elif len(parts) == 1:
        ver_str = parts[0]
    else:
        ver_str = '183'
    filename = "postgre" + ver_str + "_" + dbname + "_" + cur_time + ".gz"
    backup_dir = getBackupDir()
    file_path = backup_dir + '/' + filename

    # 确保 postgres 用户拥有对备份目录的写权限
    if not yf.isAppleSystem() and os.name != 'nt':
        yf.execShell("chown -R postgres:postgres " + backup_dir)

    port = getDbPort()

    if os.name == 'nt':
        cmd = '"' + getServerDir() + '/bin/pg_dump" -p ' + port + ' ' + dbname + ' | gzip > ' + file_path
        yf.execShell(cmd)
    else:
        # 使用 pgCmd 通过 postgres 用户调用 pg_dump 备份并 gzip
        cmd = getServerDir() + '/bin/pg_dump -p ' + port + ' ' + dbname + ' | gzip > ' + file_path
        execShellPg(cmd)

        # 还原 file_path 的所有权为 root:root 以保持安全性与普通权限
        if os.path.exists(file_path):
            yf.execShell("chown root:root " + file_path)

    if os.path.exists(file_path) and os.path.getsize(file_path) > 0:
        return yf.returnJson(True, '备份成功!')
    else:
        if os.path.exists(file_path):
            try:
                os.remove(file_path)
            except:
                pass
        return yf.returnJson(False, '备份失败! 备份文件未能成功生成，请检查数据库服务和权限。')

