        data_item['time'] = time.strftime('%Y-%m-%d %H:%M:%S', t)
        data_item['file'] = p
        rr.append(data_item)

    rr.sort(key=lambda x: x['time'], reverse=True)

    res_data = {
        'list': rr,
        'upload_dir': bkDir
    }
    return yf.returnJson(True, 'ok', res_data)


def getDbList():
